dashboard.definition:
{
  "title": "PulseForge · Linux workload: recorded Sysmon-for-Linux plus native eBPF hunt (hybrid)",
  "description": "Replay Sysmon-for-Linux events then run the existing native eBPF workload hunt in the same run.",
  "inputs": {
    "input_global_time": {
      "type": "input.timerange",
      "title": "Time range",
      "options": {
        "token": "global_time",
        "defaultValue": "-24h@h,now"
      }
    },
    "input_run": {
      "type": "input.dropdown",
      "title": "Scenario run (replay session)",
      "options": {
        "token": "run_tok",
        "defaultValue": "*",
        "items": [
          {
            "label": "All runs",
            "value": "*"
          }
        ],
        "createSearchJobOnChange": false,
        "clearDefaultOnSelection": false
      },
      "dataSources": {
        "primary": "ds_runs"
      },
      "context": {}
    },
    "input_phase": {
      "type": "input.dropdown",
      "title": "Incident phase",
      "options": {
        "token": "phase_tok",
        "defaultValue": "*",
        "items": [
          {
            "label": "All phases",
            "value": "*"
          }
        ],
        "createSearchJobOnChange": false,
        "clearDefaultOnSelection": false
      },
      "dataSources": {
        "primary": "ds_phase_list"
      },
      "context": {}
    },
    "input_index": {
      "type": "input.text",
      "title": "Index",
      "options": {
        "token": "index_tok",
        "defaultValue": "dev_test_replay"
      }
    }
  },
  "defaults": {
    "dataSources": {
      "ds.search": {
        "options": {
          "queryParameters": {
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$"
          }
        }
      }
    }
  },
  "visualizations": {
    "viz_1": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### **PulseForge** · Security investigation\n**Technology Saas · scenario telemetry**  ·  `rp_workload_sysmon_ebpf_hybrid`\n\nReplay Sysmon-for-Linux events then run the existing native eBPF workload hunt in the same run.\n\n_Live searches over the run; authentic recorded/native telemetry; industry framing is editorial._",
        "fontColor": "#ececea",
        "backgroundColor": "#17191b",
        "fontSize": "default"
      }
    },
    "viz_2": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#d4764f",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Events in run",
      "dataSources": {
        "primary": "ds_1"
      },
      "showProgressBar": true
    },
    "viz_3": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#6f9db5",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Telemetry sources (sourcetypes)",
      "dataSources": {
        "primary": "ds_2"
      },
      "showProgressBar": true
    },
    "viz_4": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#a79fc4",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Hosts observed",
      "dataSources": {
        "primary": "ds_3"
      },
      "showProgressBar": true
    },
    "viz_5": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#c9a24a",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Attack progression span",
      "dataSources": {
        "primary": "ds_4"
      },
      "showProgressBar": true
    },
    "viz_6": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#6fa387",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Progression phases observed",
      "dataSources": {
        "primary": "ds_5"
      },
      "showProgressBar": true
    },
    "viz_7": {
      "type": "splunk.singlevalue",
      "options": {
        "majorColor": "#c9786f",
        "majorFontSize": 44,
        "trendDisplay": "off",
        "sparklineDisplay": "off",
        "backgroundColor": "#22262a",
        "numberPrecision": 0
      },
      "title": "Contributing packs",
      "dataSources": {
        "primary": "ds_6"
      },
      "showProgressBar": true
    },
    "viz_8": {
      "type": "splunk.column",
      "options": {
        "stackMode": "stacked",
        "seriesColors": [
          "#d4764f",
          "#6f9db5",
          "#c9a24a",
          "#6fa387",
          "#a79fc4",
          "#c9786f",
          "#8fb0a8",
          "#b8b09a"
        ],
        "legendDisplay": "bottom",
        "yAxisTitleText": "Events",
        "xAxisTitleText": "Seconds since the first event of the run",
        "backgroundColor": "#22262a"
      },
      "title": "Incident timeline · events by phase",
      "description": "Event volume over the run's own clock, split by incident phase.",
      "dataSources": {
        "primary": "ds_7"
      },
      "showProgressBar": true
    },
    "viz_9": {
      "type": "splunk.bar",
      "options": {
        "seriesColors": [
          "#d4764f"
        ],
        "backgroundColor": "#22262a",
        "xAxisTitleText": "Events",
        "legendDisplay": "off"
      },
      "title": "Events by phase (click to filter the page)",
      "description": "Click a bar to set the Incident phase filter; choose All phases to reset.",
      "dataSources": {
        "primary": "ds_8"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.setToken",
          "options": {
            "tokens": [
              {
                "token": "phase_tok",
                "key": "name"
              }
            ]
          }
        }
      ]
    },
    "viz_10": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Detection status: **NOT VERIFIED**\nNo detection claimed.\n\n**Severity:** not asserted. PulseForge does not assign a severity to replayed telemetry; no detection has fired in this lab.",
        "fontColor": "#ececea",
        "backgroundColor": "#22262a"
      }
    },
    "viz_11": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Original analytics (Splunk Security Content)\nDetections whose published test data is a dataset replayed by this scenario:\n\n- [Cisco Isovalent - Access To Cloud Metadata Service](https://research.splunk.com/endpoint/7f2e1a9a-1e8e-4d2e-8b7c-5f2c3d6a9b21/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Cron Job Creation](https://research.splunk.com/endpoint/94531a31-a041-4777-909f-cd92ed3b71ad/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Curl Execution With Insecure Flags](https://research.splunk.com/endpoint/c16c4899-d3f7-461b-92c2-cc0ef5758855/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Late Process Execution](https://research.splunk.com/endpoint/7f4b9b8e-5d6a-4a21-9e3f-0f1e8f2d1c3a/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Non Allowlisted Image Use](https://research.splunk.com/endpoint/9f2b7b1d-6c2f-4f2d-9a8b-8a1d7c5f2e11/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Nsenter Usage in Kubernetes Pod](https://research.splunk.com/endpoint/cd07120d-4265-481a-ba0f-3b91fbc5a02f/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Pods Running Offensive Tools](https://research.splunk.com/endpoint/e9d0b9e6-2f3c-4a8a-9d61-2b6f4a9c1c2e/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Potential Escape to Host](https://research.splunk.com/endpoint/2b8a7a21-bec6-4e1f-84c4-7b319f45d2ab/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Shell Execution](https://research.splunk.com/endpoint/12345678-abcd-1234-ef00-1234567890ab/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco SA - Access to Anonymizer Services](https://research.splunk.com/network/a7c8613a-92e2-4232-b64d-bd39d33dee8b/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco SA - Automated Web Reconnaissance via HTTP Access Errors](https://research.splunk.com/network/4cd44520-d404-4ca8-b736-c9d6b86ecf31/) · Anomaly · upstream validation: NOT_TESTED\n- [Detect Large ICMP Traffic](https://research.splunk.com/network/9cd6d066-94d5-4ccd-a8b9-28c03ca91be8/) · TTP · upstream validation: NOT_TESTED\n\n_22 detections are linked in total; the first 12 are shown._",
        "fontColor": "#ececea",
        "backgroundColor": "#22262a"
      }
    },
    "viz_12": {
      "type": "splunk.table",
      "options": {
        "count": 8,
        "backgroundColor": "#22262a"
      },
      "title": "Affected hosts and assets (click a row to search its events)",
      "dataSources": {
        "primary": "ds_9"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\" | eval pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_host=\"$row.host.value$\" | sort 0 _time| head 1000",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_13": {
      "type": "splunk.table",
      "options": {
        "count": 8,
        "backgroundColor": "#22262a"
      },
      "title": "Attack progression by phase (click a row to search it)",
      "dataSources": {
        "primary": "ds_10"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\" | eval pf_phase=coalesce(netspout_pack_phase, netspout_phase) | search pf_phase=\"$row.pf_phase.value$\" | sort 0 _time| head 1000",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_14": {
      "type": "splunk.table",
      "options": {
        "count": 8,
        "backgroundColor": "#22262a"
      },
      "title": "Investigation evidence: security-relevant events (click a row for the raw search)",
      "dataSources": {
        "primary": "ds_11"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\" | eval pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_host=\"$row.host.value$\" pf_st=\"$row.sourcetype.value$\" | sort 0 _time| head 1000",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    },
    "viz_15": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Provenance and contract\n**Scenario:** `rp_workload_sysmon_ebpf_hybrid`  \n**Execution:** replay  \n**Telemetry:** Recorded or native telemetry replayed by the PulseForge replay engine.  \n**Sourcetypes:** `bro:conn:json`, `cisco:cloud_security:dns`, `cisco:cloud_security:firewall`, `cisco:cloud_security:proxy`, `cisco:isovalent`, `cisco:isovalent:processConnect`, `cisco:isovalent:processExec`, `gcp:audit`, `opentelemetry:otlp`, `sysmon:linux`\n\n**Correlation:** only what the source telemetry itself carries; nothing is added by PulseForge.",
        "fontColor": "#ececea",
        "backgroundColor": "#22262a"
      }
    },
    "viz_16": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "### Original analytics (Splunk Security Content)\nDetections whose published test data is a dataset replayed by this scenario:\n\n- [Cisco Isovalent - Access To Cloud Metadata Service](https://research.splunk.com/endpoint/7f2e1a9a-1e8e-4d2e-8b7c-5f2c3d6a9b21/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Cron Job Creation](https://research.splunk.com/endpoint/94531a31-a041-4777-909f-cd92ed3b71ad/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Curl Execution With Insecure Flags](https://research.splunk.com/endpoint/c16c4899-d3f7-461b-92c2-cc0ef5758855/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Late Process Execution](https://research.splunk.com/endpoint/7f4b9b8e-5d6a-4a21-9e3f-0f1e8f2d1c3a/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Non Allowlisted Image Use](https://research.splunk.com/endpoint/9f2b7b1d-6c2f-4f2d-9a8b-8a1d7c5f2e11/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Nsenter Usage in Kubernetes Pod](https://research.splunk.com/endpoint/cd07120d-4265-481a-ba0f-3b91fbc5a02f/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Pods Running Offensive Tools](https://research.splunk.com/endpoint/e9d0b9e6-2f3c-4a8a-9d61-2b6f4a9c1c2e/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Potential Escape to Host](https://research.splunk.com/endpoint/2b8a7a21-bec6-4e1f-84c4-7b319f45d2ab/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco Isovalent - Shell Execution](https://research.splunk.com/endpoint/12345678-abcd-1234-ef00-1234567890ab/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco SA - Access to Anonymizer Services](https://research.splunk.com/network/a7c8613a-92e2-4232-b64d-bd39d33dee8b/) · Anomaly · upstream validation: NOT_TESTED\n- [Cisco SA - Automated Web Reconnaissance via HTTP Access Errors](https://research.splunk.com/network/4cd44520-d404-4ca8-b736-c9d6b86ecf31/) · Anomaly · upstream validation: NOT_TESTED\n- [Detect Large ICMP Traffic](https://research.splunk.com/network/9cd6d066-94d5-4ccd-a8b9-28c03ca91be8/) · TTP · upstream validation: NOT_TESTED\n\n_22 detections are linked in total; the first 12 are shown._",
        "fontColor": "#ececea",
        "backgroundColor": "#22262a"
      }
    },
    "viz_17": {
      "type": "splunk.table",
      "options": {
        "count": 8,
        "backgroundColor": "#22262a"
      },
      "title": "Raw event evidence for the run (click a row for the search)",
      "dataSources": {
        "primary": "ds_12"
      },
      "showProgressBar": true,
      "eventHandlers": [
        {
          "type": "drilldown.linkToSearch",
          "options": {
            "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\" | eval pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_host=\"$row.host.value$\" pf_st=\"$row.sourcetype.value$\" | sort 0 _time| head 1000",
            "earliest": "$global_time.earliest$",
            "latest": "$global_time.latest$",
            "type": "custom",
            "newTab": true
          }
        }
      ]
    }
  },
  "dataSources": {
    "ds_1": {
      "type": "ds.search",
      "name": "Events in run",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats count as value"
      }
    },
    "ds_2": {
      "type": "ds.search",
      "name": "Telemetry sources (sourcetypes)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats dc(pf_st) as value"
      }
    },
    "ds_3": {
      "type": "ds.search",
      "name": "Hosts observed",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats dc(pf_host) as value"
      }
    },
    "ds_4": {
      "type": "ds.search",
      "name": "Attack progression span",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats min(_time) as a max(_time) as z | eval value=tostring(round(z-a),\"duration\") | table value"
      }
    },
    "ds_5": {
      "type": "ds.search",
      "name": "Progression phases observed",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats dc(pf_phase) as value"
      }
    },
    "ds_6": {
      "type": "ds.search",
      "name": "Contributing packs",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | eval pk=coalesce(netspout_source_pack, netspout_scenario_id) | stats dc(pk) as value"
      }
    },
    "ds_7": {
      "type": "ds.search",
      "name": "Incident timeline · events by phase",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\"| eventstats min(_time) as pf_t0 max(_time) as pf_t1 | eval pf_w=max(1, ceil((pf_t1-pf_t0)/60)), pf_sec=floor((_time-pf_t0)/pf_w)*pf_w | stats count by pf_sec, pf_phase | xyseries pf_sec pf_phase count | sort pf_sec | fillnull value=0"
      }
    },
    "ds_8": {
      "type": "ds.search",
      "name": "Events by phase (click to filter the page)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats count by pf_phase | sort - count"
      }
    },
    "ds_9": {
      "type": "ds.search",
      "name": "Affected hosts and assets (click a row to search its events)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats count as events, dc(pf_phase) as phases, values(pf_st) as sources, min(_time) as first by pf_host | eval first=strftime(first,\"%H:%M:%S\") | sort - events | head 25 | rename pf_host as host"
      }
    },
    "ds_10": {
      "type": "ds.search",
      "name": "Attack progression by phase (click a row to search it)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | stats min(_time) as t0 max(_time) as t1 count as events by pf_phase | sort t0 | eval start=strftime(t0,\"%H:%M:%S\"), seconds=round(t1-t0) | fields start pf_phase events seconds"
      }
    },
    "ds_11": {
      "type": "ds.search",
      "name": "Investigation evidence: security-relevant events (click a row for the raw search)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | sort 0 _time | eval time=strftime(_time,\"%H:%M:%S\"), message=substr(_raw,1,200) | table time pf_phase pf_host pf_st message | rename pf_host as host, pf_st as sourcetype | head 200"
      }
    },
    "ds_12": {
      "type": "ds.search",
      "name": "Raw event evidence for the run (click a row for the search)",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\"| eval pf_phase=coalesce(netspout_pack_phase, netspout_phase), pf_host=mvindex(host,-1), pf_st=mvindex(sourcetype,0) | search pf_phase=\"$phase_tok$\" | sort 0 _time | eval time=strftime(_time,\"%H:%M:%S\"), message=substr(_raw,1,200) | table time pf_phase pf_host pf_st message | rename pf_host as host, pf_st as sourcetype | head 200"
      }
    },
    "ds_runs": {
      "type": "ds.search",
      "name": "Run list",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" | stats latest(_time) as t count by netspout_replay_session | sort - t | eval label=netspout_replay_session.\" · \".strftime(t,\"%m-%d %H:%M\").\" · \".count.\" events\" | table label netspout_replay_session"
      }
    },
    "ds_phase_list": {
      "type": "ds.search",
      "name": "Phase list",
      "options": {
        "query": "index=$index_tok$ netspout_scenario_id=\"rp_workload_sysmon_ebpf_hybrid\" netspout_replay_session=\"$run_tok$\" | eval pf_phase=coalesce(netspout_pack_phase, netspout_phase) | stats count by pf_phase | sort pf_phase | eval label=pf_phase | table label pf_phase"
      }
    }
  },
